-- New Tinkertown, the ruined ground west: roaming radii for the sludges and slimes
-- Both entries roamed within 3 yd, which is far tighter than they keep to. The
-- guid lists are only the spawns whose roam was actually measured; the remaining
-- 15 Toxic Sludges and 3 Living Contamination stay at 3 yd.

-- Toxic Sludge: 3 -> 6 yd.
UPDATE `creature` SET `wander_distance`=6 WHERE `id`=42184 AND `guid` IN (
    167531, 167532, 167533, 167726, 167728, 167885, 168018, 168341, 168423, 168425,
    168426, 168435, 168436, 168439, 168440, 168441, 168442, 168446, 168539, 168890,
    168953, 168954, 168977, 168995, 169113, 169130, 169143, 169145, 169146, 169149,
    169150, 169155, 169170);

-- Living Contamination: 3 -> 11 yd.
UPDATE `creature` SET `wander_distance`=11 WHERE `id`=42185 AND `guid` IN (
    167530, 167725, 167727, 167884, 167886, 168019, 168325, 168437, 168535, 168544,
    168546, 168677, 168994, 168996, 169010, 169115, 169147, 169168, 169172, 169173,
    169179, 169214);

